exercise.description:
Сначала диагностируйте четыре независимых фрагмента по номерам 0–3; не исполняйте их. solve(a,b) принимает номер фрагмента a; b не используется. Верните код первичного дефекта: 0 — безопасно в показанных границах; 1 — double delete; 2 — use-after-free; 3 — dangling reference при возврате; 4 — нарушение заявленного договора заимствования; 5 — цикл сильного владения; 6 — move constructor оставил двух владельцев. Для 4 и 6 выбирайте причину, а не последующий double delete. В комментарии к решению укажите строку, событие окончания жизни и владельца. После проверки диагноза перейдите к заданию 2 и исправьте исходник.

Фрагмент 0:
// Контракт: log только читает значение.
void log(int* p) { std::cout << *p << "\n"; delete p; }

Фрагмент 1:
int consume(std::unique_ptr<int> p) { return *p; }

Фрагмент 2:
// Контракт: вызывающий остаётся владельцем.
int* borrow(std::unique_ptr<int>& p) { return p.release(); }

Фрагмент 3:
auto owner = std::make_shared<int>(7); auto copy = owner; int result = *copy;

exercise.starterCode:
#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

// Реализуйте типы и операции из условия.
int solve(int a,int b){
    (void)a; (void)b;
    return 0;
}

exercise.referenceSolution:
#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

int solve(int a,int b){(void)b; const int diagnosis[4]={4,0,4,0}; return diagnosis[a];}

