#include <utility>
#include <string>

int inspect(int* p){int x=*p;delete p;return x;}
int solve(int a,int b){auto owner=std::make_unique<int>(a);return inspect(owner.get())+b;}

additionalExercises.referenceSolution:
#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

int inspect(const int& x) { return x; }
int solve(int a, int b) { auto owner = std::make_unique<int>(a); return inspect(*owner) + b; }
